import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

/// @dev A rights holder that is a contract, so its draw and its redemption against another borrower share
/// one transaction. The ORDER is the point: draw first, cancel the honest debt second.
contract Inheritor {
    ParameterizedVault private immutable vault;

    constructor(ParameterizedVault vault_, MockIMD imd_) {
        vault = vault_;
        imd_.approve(address(vault_), type(uint256).max);
    }

    function drawThenCancel(address candidate, uint256 collateral, uint256 debt, uint256 cancel) external {
        vault.lock(collateral);
        vault.draw(debt);
        vault.cash(cancel, 0, candidate);
    }

    function earn(uint256 amount) external {
        vault.earn(amount);
    }
}

contract IWFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 days;
    uint256 private value;
    uint64 private updatedAt;

    constructor(uint256 v) {
        value = v;
        updatedAt = uint64(block.timestamp);
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, updatedAt);
    }

    function isStale() external pure returns (bool) {
        return false;
    }
}

contract IWMirror is ISwarmFeed {
    ISwarmFeed private immutable primary;

    constructor(ISwarmFeed p) {
        primary = p;
    }

    function latestValue() external view returns (uint256, uint64) {
        return primary.latestValue();
    }

    function isStale() external view returns (bool) {
        return primary.isStale();
    }

    function maxAge() external view returns (uint256) {
        return primary.maxAge();
    }
}

contract IWAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

/// @notice The sweep panel's high (cancel another borrower's warm debt, then draw) was closed by banking
/// warmth per position. The mirror order is open: DRAW first, then cancel the warm debt. The decrease
/// never clamps the aggregate lag (live debt after the cancellation is not below it), the leaver banks
/// nothing, and the zero-second debt stands in for the warm debt that left.
contract InheritedWarmthTest is Test {
    address private constant HONEST = address(0x4043);
    address private constant HELPER = address(0x4E1);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    MockWorkOracle private oracle;
    Inheritor private attacker;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new IWAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        // 1 IMD = 1/2000 ETH and 1 ETH = $2000: the vault prices IMD at exactly $1.
        IWFeed primary = new IWFeed(uint256(1 ether) * 1e18 / 2000 ether);
        IWFeed health = new IWFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new IWMirror(primary))
        );
        stable = vault.stablecoin();
        oracle = MockWorkOracle(address(vault.oracle()));
        attacker = new Inheritor(vault, imd);
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(HONEST, 2_000 ether);
        imd.mint(HELPER, 200 ether);
        imd.mint(address(attacker), 2_000 ether);
        oracle.grantRights(address(attacker), 1_000 ether);
        vm.stopPrank();
        vm.prank(HONEST);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(HELPER);
        imd.approve(address(vault), type(uint256).max);

        // Minting from work switched on the governed way.
        Parameters params = vault.parameters();
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(0.01 ether);
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();

        // An honest borrower at 200% (inside the redeemable band) whose imdUSD the attacker holds.
        vm.startPrank(HONEST);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        stable.transfer(address(attacker), 1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 3 days);
        // A checkpoint, and 50 imdUSD of fee money for the attacker's eventual repayments.
        vm.startPrank(HELPER);
        vault.lock(200 ether);
        vault.draw(50 ether);
        stable.transfer(address(attacker), 50 ether);
        vm.stopPrank();
        (uint256 warm,) = vault.laggedNow();
        assertGe(warm, 1_000 ether, "the honest debt is warm");
    }

    function _nextBlock() private {
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 12);
    }

    /// @dev One transaction: lock 2,000, draw 1,000, cash 1,000 against HONEST. Afterwards the only
    /// principal above the fee residue is the attacker's, zero seconds old.
    function test_drawThenCancelDoesNotInheritTheWarmth() public {
        attacker.drawThenCancel(HONEST, 2_000 ether, 1_000 ether, 1_000 ether);
        assertLt(vault.debtOf(HONEST), 1 ether, "the honest principal is cancelled");
        assertEq(vault.totalDebt() - vault.debtOf(HONEST) - 50 ether, 1_000 ether, "the attacker's principal replaced it");
        // EXPECTED: the warm principal left, so the lag holds at most the helper's 50 (one checkpoint old)
        // and the residue; the attacker's 1,000 warms from zero over a day.
        assertLt(vault.laggedDebt(), 100 ether, "zero-second debt must not read as warm");
    }

    /// @dev The consequence: the work ceiling in the next block is a quarter of the attacker's fresh debt.
    function test_freshDebtAuthorisesNoWorkInTheNextBlock() public {
        attacker.drawThenCancel(HONEST, 2_000 ether, 1_000 ether, 1_000 ether);
        _nextBlock();
        // EXPECTED: earnLine is about 12.5 (a quarter of the helper's 50, barely warmed) and the earn reverts.
        assertLt(vault.earnLine(), 20 ether, "the ceiling reads warm debt only");
        vm.expectRevert(CDPVault.WorkCeilingReached.selector);
        attacker.earn(250 ether);
    }
}

