/// @notice The burn tally (BURNED_THIS_TX_SLOT) is transient, so it nets a repayment out of the backing
/// denominator and the fee base only inside ONE transaction. The same wipe / cash / draw as three
/// consecutive transactions (one block, or seconds apart) is paid above pro rata and pins the fee at
/// the cap exactly as the sweep panel's two mediums described, and the per-position bank credits the
/// redraw so the churn leaves nothing behind. Under foundry.toml `isolate = true` each top-level call
/// below is its own transaction.
contract AdjacentTxBurnTest is Test {
    address private constant BORROWER = address(0xB0);
    address private constant OTHER = address(0x07);
    address private constant REDEEMER = address(0x4ED);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    ATFeed private primary;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new ATAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new ATFeed(uint256(1 ether) * 1e18 / 2000 ether); // $1 per IMD
        ATFeed health = new ATFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new ATMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 10_000 ether);
        imd.mint(OTHER, 10_000 ether);
        vm.stopPrank();
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(OTHER);
        imd.approve(address(vault), type(uint256).max);
    }

    function _price(uint256 usdPerImd) private {
        primary.setValue(usdPerImd * 1e18 / 2000 ether);
    }

    /// @dev The sweep panel's medium #3, one transaction apart instead of inside one. The borrower is in
    /// the 170-200% band after a price fall, so repaying 150 moves neither its collateral term nor the
    /// numerator; only the supply (the denominator) falls, and the lag is restored by the redraw.
    function test_adjacentWipeCashDrawIsPaidProRata() public {
        vm.startPrank(BORROWER);
        vault.lock(5_780 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.startPrank(OTHER);
        vault.lock(5_100 ether);
        vault.draw(3_000 ether);
        stable.transfer(BORROWER, 3_000 ether);
        vm.stopPrank();
        _price(0.294 ether); // borrower at 170%, OTHER at 50%
        vm.prank(BORROWER);
        vault.lock(1);
        vm.prank(OTHER);
        vault.lock(1);
        vm.warp(block.timestamp + 3 days);
        assertApproxEqRel(vault.backingPerUnit(), 0.79968e18, 1e15, "backing below par: the regime the cap binds in");

        uint256 snapshot = vm.snapshotState();
        vm.prank(BORROWER);
        uint256 plain = vault.cash(500 ether, 0, BORROWER);
        vm.revertToState(snapshot);

        // Three transactions, nothing in between.
        vm.prank(BORROWER);
        vault.wipe(150 ether);
        vm.prank(BORROWER);
        uint256 churned = vault.cash(500 ether, 0, BORROWER);
        vm.prank(BORROWER);
        vault.draw(150 ether);

        // EXPECTED: the same debt and supply before and after, so the same payout: about 1,292 IMD.
        // ACTUAL: the churned redemption is paid about 3.9% more, from every other holder's backing.
        assertLe(churned, plain + plain / 1000, "a repayment one transaction earlier must not raise the payout");
    }

    /// @dev The sweep panel's medium #4, one transaction apart: a dominant borrower's repayment shrinks
    /// the fee base, a small reserve-funded burn pins the base rate at the cap, the redraw restores the
    /// position and the lag.
    function test_adjacentWipeCashDrawDoesNotPinTheFee() public {
        vm.startPrank(BORROWER);
        vault.lock(2_000 ether);
        vault.draw(900 ether);
        vm.stopPrank();
        vm.startPrank(OTHER);
        vault.lock(200 ether);
        vault.draw(100 ether);
        stable.transfer(BORROWER, 9 ether);
        vm.stopPrank();
        address treasury = address(vault.treasury());
        vm.prank(APPROVED_OPERATOR);
        imd.mint(treasury, 100 ether); // the redemption is reserve-funded
        assertEq(stable.totalSupply(), 1_000 ether);
        assertEq(vault.redemptionBaseRate(), 0);
        assertEq(vault.redemptionFeeBps(9 ether), 95, "9 of 1,000 at divisor 2 is 45 bps over the 50 floor");

        vm.prank(BORROWER);
        vault.wipe(900 ether);
        vm.prank(BORROWER);
        vault.cash(9 ether, 0, address(0));
        vm.prank(BORROWER);
        vault.draw(900 ether);

        // EXPECTED: 45 bps, the increase for a 9-of-1,000 burn. ACTUAL: the 450 bps cap, for everyone.
        assertEq(vault.redemptionBaseRate(), 0.0045e18, "the fee base is the supply that existed before the churn");
    }
}

