/// @notice `_reduceDebt` banks the debt-side warmth BEFORE `_advanceLag` runs, against the stored
/// `laggedDebt` of the last checkpoint rather than the lag as of now. In a quiet vault (no checkpoint since
/// the position's own draw) the stored figure excludes the position's debt entirely, so the wipe banks
/// nothing, the clamp then drops the advanced lag, and the redraw warms from zero: the final panel's medium
/// (a borrower's own wipe-and-redraw depresses backing for a day) survives exactly when nobody else has
/// transacted. The project's own test hides it by calling `_feeMoney` ("a checkpoint") before the churn.
contract StaleBankTest is Test {
    address private constant BORROWER = address(0xB0);
    address private constant OTHER = address(0x07);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new SBAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        SBFeed primary = new SBFeed(uint256(1 ether) * 1e18 / 2000 ether); // $1 per IMD
        SBFeed health = new SBFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new SBMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 10_000 ether);
        imd.mint(OTHER, 10_000 ether);
        vm.stopPrank();
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(OTHER);
        imd.approve(address(vault), type(uint256).max);
    }

    function test_aQuietVaultBanksTheWipeAndCreditsTheRedraw() public {
        // Fee money first, so the borrower's own draw is the LAST checkpoint before its wipe.
        vm.startPrank(OTHER);
        vault.lock(200 ether);
        vault.draw(50 ether);
        stable.transfer(BORROWER, 50 ether);
        vm.stopPrank();
        vm.startPrank(BORROWER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        // Three quiet days: nobody touches the vault, so the stored laggedDebt is still the deployment-block
        // figure (0: both draws landed in the block the vault was deployed in) while laggedNow() is 1,050.
        vm.warp(block.timestamp + 3 days);
        (uint256 warm,) = vault.laggedNow();
        assertEq(warm, 1_050 ether, "the debt is warm");
        assertLt(vault.laggedDebt(), 1 ether, "but the stored checkpoint predates the borrower's draw");

        vm.prank(BORROWER);
        vault.wipe(500 ether);
        // A decrease counts at once.
        assertApproxEqAbs(vault.laggedDebt(), 550 ether, 1 ether);
        vm.prank(BORROWER);
        vault.draw(500 ether);
        (uint256 after_,) = vault.laggedNow();
        // EXPECTED (NatSpec 893-906): the same position's return within a day is credited: about 1,050.
        // ACTUAL: nothing was banked (lost = 50 - 550 saturates to 0), so the lag stays at 550 and the 500
        // warms again over a day; backingPerUnit and earnLine read it for that day.
        assertApproxEqAbs(after_, 1_050 ether, 1 ether, "a borrower's own wipe-and-redraw must leave the lag where it was");
    }
}

