        oracle = MockWorkOracle(address(vault.oracle()));
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 2_000 ether);
        imd.mint(HELPER, 200 ether);
        oracle.grantRights(WORKER, 1_000 ether);
        vm.stopPrank();
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(HELPER);
        imd.approve(address(vault), type(uint256).max);
        Parameters params = vault.parameters();
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(0.01 ether);
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();
    }

    /// The borrower holds 2,000 / 1,000 for three quiet days, then repays and redraws in two transactions
    /// of the same block. The design (NatSpec of _bank) credits the return; the code does not.
    function test_aQuietDayThenWipeAndRedrawWarmsFromZero() public {
        // imdUSD for the fees, borrowed by an unrelated position BEFORE the quiet period.
        vm.startPrank(HELPER);
        vault.lock(200 ether);
        vault.draw(50 ether);
        stable.transfer(BORROWER, 50 ether);
        vm.stopPrank();
        vm.startPrank(BORROWER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 3 days); // nobody touches the vault
        (uint256 lagDebt,) = vault.laggedNow();
        assertEq(lagDebt, 1_050 ether, "every unit of debt is warm");
        assertEq(vault.earnLine(), 262.5 ether, "the ceiling credits all of it");
        vm.startPrank(BORROWER);
        vault.wipe(vault.debtOf(BORROWER));
        vault.draw(1_000 ether);
        vm.stopPrank();
        (lagDebt,) = vault.laggedNow();
        // EXPECTED: 1,050e18 (the position's own capital came back within the day).
        // ACTUAL: 50e18, the helper's; the borrower's 1,000 warms from zero and earnLine is 12.5.
        assertGe(lagDebt, 1_049 ether, "the same position's return within a day is credited back");
        assertGe(vault.earnLine(), 262 ether, "and the work ceiling is where it was");
    }

    /// With work-minted supply outstanding the same churn drives the lagged backing to the reserve
    /// (zero here), closing cash for everyone, for the length of a warm-up.
    function test_aQuietDayThenWipeAndRedrawClosesRedemption() public {
        vm.startPrank(BORROWER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 1 days);
        vm.startPrank(WORKER);
