        stable.transfer(BORROWER, 10 ether); // for the fees
        stable.transfer(REDEEMER, 10 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 1 days); // quiet again
        assertEq(vault.backingPerUnit(), 1e18, "fully backed before the churn");
        vm.startPrank(BORROWER);
        vault.wipe(vault.debtOf(BORROWER));
        vault.draw(1_000 ether);
        vm.stopPrank();
        // EXPECTED: unchanged, 1e18. ACTUAL: 0, and cash reverts ZeroAmount.
        assertEq(vault.backingPerUnit(), 1e18, "an own-position round trip must not move backing");
        vm.prank(REDEEMER);
        vault.cash(10 ether, 0, BORROWER);
    }
}

