/// @dev A borrower that is a contract, so a wipe and a redraw can share one transaction.
contract SChurner {
    ParameterizedVault private immutable vault;

    constructor(ParameterizedVault vault_, MockIMD imd_) {
        vault = vault_;
        imd_.approve(address(vault_), type(uint256).max);
    }

    function open(uint256 collateral, uint256 debt) external {
        vault.lock(collateral);
        vault.draw(debt);
    }

    function wipeAndRedraw(uint256 amount) external {
        vault.wipe(amount);
        vault.draw(amount);
    }
}

/// @notice `_reduceDebt` banks the debt side BEFORE `_advanceLag` runs, from the STORED laggedDebt rather
/// than the current one. On a vault with no checkpoint since the position's capital arrived (a quiet day,
/// which the NatSpec says credits capital in full) the stored figure is the pre-warm-up one, so the
/// repayment banks nothing, the clamp then drops the lag to the post-repayment level, and the same
/// position's redraw is credited nothing: the final panel's medium (atomic wipe-and-redraw drives the
/// lagged backing to zero for a day) is back whenever the lag's last checkpoint predates the warm-up.
contract Proof_StaleBankOnRepayment is Test {
    address private constant WORKER = address(0xCA);
    address private constant REDEEMER = address(0x4E1);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    MockWorkOracle private oracle;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new SAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        SFeed primary = new SFeed(uint256(1 ether) * 1e18 / 2000 ether); // IMD = $1
        SFeed health = new SFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new SMirror(primary))
        );
        stable = vault.stablecoin();
        oracle = MockWorkOracle(address(vault.oracle()));
        vm.prank(APPROVED_OPERATOR);
        oracle.grantRights(WORKER, 1_000 ether);
        Parameters params = vault.parameters();
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(0.01 ether);
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();
    }

    function test_quietDayThenWipeAndRedrawKeepsTheWarmth() public {
        SChurner churner = new SChurner(vault, imd);
        vm.prank(APPROVED_OPERATOR);
        imd.mint(address(churner), 2_000 ether);
        churner.open(2_000 ether, 1_000 ether);
        // A quiet day: nobody touches the vault, so there is no checkpoint and laggedNow() warms to the
        // live figure while the STORED laggedDebt stays at zero.
        vm.warp(block.timestamp + 1 days);
        (uint256 lagDebt, uint256 lagSecured) = vault.laggedNow();
        assertEq(lagDebt, 1_000 ether, "a quiet day credits the debt in full");
        assertEq(lagSecured, 2_000 ether, "and the collateral");
        assertEq(vault.laggedDebt(), 0, "the stored figure has not been checkpointed since the draw");
        assertEq(vault.earnLine(), 250 ether);

        // The same position repays and redraws in one transaction. The fix's own promise: the lag is
        // left where it was, the debt's warmth comes back from the position's bank.
        churner.wipeAndRedraw(1_000 ether);
        (lagDebt,) = vault.laggedNow();
        assertEq(lagDebt, 1_000 ether, "debt that left and came back to the same position within a day is warm");
        assertEq(vault.earnLine(), 250 ether, "the ceiling still credits the day held");
    }

    /// @dev The consequence the final panel's medium described: with work-minted supply outstanding, the
    /// dominant borrower's wipe-and-redraw drives the lagged backing to nothing and closes `cash`.
    function test_quietDayThenWipeAndRedrawClosesRedemption() public {
        SChurner churner = new SChurner(vault, imd);
        vm.prank(APPROVED_OPERATOR);
        imd.mint(address(churner), 2_000 ether);
        churner.open(2_000 ether, 1_000 ether);
        vm.warp(block.timestamp + 1 days);
        vm.startPrank(WORKER);
        vault.earn(250 ether); // the ceiling after a quiet day; earn is not a lag checkpoint
        stable.transfer(REDEEMER, 250 ether);
        vm.stopPrank();
        assertEq(vault.backingPerUnit(), 1e18, "fully backed before the churn");
        churner.wipeAndRedraw(1_000 ether);
        assertGe(vault.backingPerUnit(), 0.99e18, "the same position's round trip must not move the backing");
        vm.prank(REDEEMER);
        uint256 out = vault.cash(10 ether, 0, address(0));
        assertGt(out, 9 ether, "a redeemer is paid against par, not against a lag the churn zeroed");
    }

    function test_quietDayThenWipeThenDrawAcrossTransactions() public {
        vm.prank(APPROVED_OPERATOR);
        imd.mint(WORKER, 2_000 ether);
        vm.startPrank(WORKER);
        imd.approve(address(vault), type(uint256).max);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 1 days);
        (uint256 before,) = vault.laggedNow();
        assertEq(before, 1_000 ether);
        vm.prank(WORKER);
        vault.wipe(1_000 ether);
        vm.prank(WORKER);
        vault.draw(1_000 ether);
        (uint256 after_,) = vault.laggedNow();
        assertEq(after_, before, "the same position's return in the next transaction is credited from its bank");
    }
}

