/// @notice `_bank` keeps ONE `bankAt` for both sides but checks expiry only when the side being touched
/// holds a bank. A position that banked secured collateral a month ago (expired, never touched since)
/// wipes one wei: the DEBT side holds no bank, so no expiry check runs, and the one-wei decrease rewrites
/// `bankAt` to now. The month-old secured bank is alive again and the next lock is credited to the lag at
/// once, where the NatSpec says a position that stays smaller for a day forfeits its bank.
contract Proof_BankResurrected is Test {
    address private constant BORROWER = address(0xB0B);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    RFeed private primary;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new RAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new RFeed(uint256(1 ether) * 1e18 / 2000 ether); // IMD = $1
        RFeed health = new RFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new RMirror(primary))
        );
        stable = vault.stablecoin();
        vm.prank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 2_000 ether);
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
    }

    function test_aMonthOldSecuredBankIsRevivedByAOneWeiRepayment() public {
        vm.startPrank(BORROWER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 2 days);
        // Withdraw down to 170%: the secured term falls 2,000 -> 1,710 and the lag loses 290, banked on the position.
        vm.prank(BORROWER);
        vault.free(290 ether);
        (, uint256 lagSecured) = vault.laggedNow();
        assertEq(lagSecured, 1_710 ether, "a decrease counts at once");

        // A month smaller: the bank has expired by the NatSpec's rule ("a position that stays smaller for
        // a day forfeits the bank and warms again like any new capital").
        vm.warp(block.timestamp + 30 days);
        // Fees are paid first, so one wei of PRINCIPAL is the accrued fee plus one wei. The debt side holds
        // no bank, so no expiry check runs, and this decrease rewrites `bankAt` for the secured side too.
        uint256 oneWeiOfPrincipal = vault.stabilityFeeOf(BORROWER) + 1;
        vm.prank(BORROWER);
        vault.wipe(oneWeiOfPrincipal);
        vm.prank(BORROWER);
        vault.lock(290 ether);

        // EXPECTED: the re-locked 290 warms from zero, so the lagged secured figure is still 1,710 a moment
        // later. ACTUAL: credited at once, 2,000.
        (, lagSecured) = vault.laggedNow();
        assertLe(lagSecured, 1_710 ether + 1 ether, "capital away for a month must warm again like new capital");
    }
}

