/// @dev The sweep panel's attacker with the two steps in the other order: draw FIRST, then cancel the
/// honest borrower's warm debt with the imdUSD just drawn.
contract Reverser {
    ParameterizedVault private immutable vault;

    constructor(ParameterizedVault vault_, MockIMD imd_) {
        vault = vault_;
        imd_.approve(address(vault_), type(uint256).max);
    }

    function open(uint256 collateral, uint256 debt) external {
        vault.lock(collateral);
        vault.draw(debt);
    }

    function cancel(address candidate, uint256 amount) external {
        vault.cash(amount, 0, candidate);
    }

    function earn(uint256 amount) external {
        vault.earn(amount);
    }
}

/// @notice Q1(b): warmth banked per position (973369e) only covers a decrease FOLLOWED by an increase. An
/// increase followed by a decrease leaves the aggregate lag where it stood, so the warmth of the debt that
/// left is inherited by the zero-second debt that arrived before it. The sweep panel's high finding is
/// reopened by swapping the two calls: draw, then cash (or bite, or cover) against the honest position.
contract WarmthByOrderingTest is Test {
    address private constant HONEST = address(0x4043);
    address private constant HELPER = address(0x4E1);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    MockWorkOracle private oracle;
    Reverser private attacker;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new OrderAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        // 1 IMD = 1/2000 ETH and 1 ETH = $2000, so the vault prices IMD at exactly $1.
        OrderFeed primary = new OrderFeed(uint256(1 ether) * 1e18 / 2000 ether);
        OrderFeed health = new OrderFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new OrderMirror(primary))
        );
        stable = vault.stablecoin();
        oracle = MockWorkOracle(address(vault.oracle()));
        attacker = new Reverser(vault, imd);
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(HONEST, 2_000 ether);
        imd.mint(HELPER, 200 ether);
        imd.mint(address(attacker), 2_000 ether);
        oracle.grantRights(address(attacker), 1_000 ether);
        vm.stopPrank();
        vm.prank(HELPER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(HONEST);
        imd.approve(address(vault), type(uint256).max);
        // Minting from work switched on the governed way.
        Parameters params = vault.parameters();
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(0.01 ether);
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();
    }

    function test_drawThenCancelInheritsTheHonestBorrowersWarmth() public {
        // The honest borrower is at 200%, inside the redeemable band (< mat + gap = 220), and warm.
        vm.startPrank(HONEST);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 3 days);
        // A checkpoint by an unrelated position: the honest debt is warm in storage too.
        vm.startPrank(HELPER);
        vault.lock(200 ether);
        vault.draw(50 ether);
        vm.stopPrank();
        (uint256 warm,) = vault.laggedNow();
        assertGe(warm, 1_000 ether, "the honest debt is warm");

        // Transaction 1: the attacker draws 1,000 (zero seconds old: it warms from zero, as designed).
        attacker.open(2_000 ether, 1_000 ether);
        (uint256 afterDraw,) = vault.laggedNow();
        assertLt(afterDraw, 1_001 ether, "a draw by a new position adds no warmth");

        // Transaction 2, next block: the attacker cancels the honest debt with the imdUSD it just drew.
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 12);
        attacker.cancel(HONEST, 1_000 ether);
        assertLt(vault.debtOf(HONEST), 1 ether, "the honest debt is gone");

        // EXPECTED: the honest warmth left with the honest debt; the attacker's debt is a block old and
        // the helper's 50 is three blocks old, so the lag is under 100 and the ceiling is under 25.
        // ACTUAL: the lag still reads the honest 1,000, now standing on the attacker's zero-second debt.
        (uint256 lag,) = vault.laggedNow();
        assertLt(lag, 100 ether, "the honest debt's warmth did not move to the attacker's debt");
        assertLt(vault.earnLine(), 25 ether, "and the work ceiling does not read it");
        vm.expectRevert(CDPVault.WorkCeilingReached.selector);
        attacker.earn(250 ether);
    }
}

