pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {ParameterizedVault} from "src/ParameterizedVault.sol";
import {CDPVault} from "src/CDPVault.sol";
import {ImdUSD} from "src/ImdUSD.sol";
import {MockIMD} from "src/MockIMD.sol";
import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {Parameters} from "src/Parameters.sol";
import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

contract KeptFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 days;
    uint256 private value;
    uint64 private updatedAt;

    constructor(uint256 v) {
        value = v;
        updatedAt = uint64(block.timestamp);
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, updatedAt);
    }

    function isStale() external pure returns (bool) {
        return false;
    }
}

contract KeptMirror is ISwarmFeed {
    ISwarmFeed private immutable primary;

    constructor(ISwarmFeed p) {
        primary = p;
    }

    function latestValue() external view returns (uint256, uint64) {
        return primary.latestValue();
    }

    function isStale() external view returns (bool) {
        return primary.isStale();
    }

    function maxAge() external view returns (uint256) {
        return primary.maxAge();
    }
}

contract KeptAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

/// @notice Q1(c): `_bank` resets `bankAt` to now on EVERY decrease that costs the lag anything, and only
/// forfeits an expired bank when the bank being accessed is nonzero. A one-wei withdrawal a day keeps a
/// bank alive indefinitely, so capital that stayed away for five days comes back warm at once, where the
/// NatSpec says "a position that stays smaller for a day forfeits the bank and warms again like any new
/// capital".
contract BankKeptPastItsDayTest is Test {
    address private constant BORROWER = address(0xB0B);
    address private constant HELPER = address(0x4E1);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new KeptAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        KeptFeed primary = new KeptFeed(uint256(1 ether) * 1e18 / 2000 ether);
        KeptFeed health = new KeptFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new KeptMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 2_000 ether);
        imd.mint(HELPER, 200 ether);
        vm.stopPrank();
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(HELPER);
        imd.approve(address(vault), type(uint256).max);
        Parameters params = vault.parameters();
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(0.01 ether);
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();
    }

    function test_aOneWeiDecreaseADayKeepsTheBankAliveForever() public {
        // 200%: the secured term is bounded by the collateral, so a withdrawal lowers it one for one.
        vm.startPrank(BORROWER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 2 days);
        // A checkpoint by an unrelated, debt-free position: the borrower's capital is warm in storage.
        vm.prank(HELPER);
        vault.lock(200 ether);
        // The borrower withdraws 200 (still healthy at ~179%): the lag loses 200 of secured collateral and the
        // position banks it, dated now.
        vm.prank(BORROWER);
        vault.free(200 ether);
        uint256 laggedAfterLeaving = vault.laggedSecured();
        assertEq(laggedAfterLeaving, vault.securedCollateral(), "a decrease counts at once");

        // Five days away, one wei withdrawn each day: every decrease re-dates the bank.
        for (uint256 day; day < 5; ++day) {
            vm.warp(block.timestamp + 1 days);
            vm.prank(BORROWER);
            vault.free(1);
        }
        uint256 laggedBeforeReturn = vault.laggedSecured();

        // The 200 come back after five days away.
        vm.prank(BORROWER);
        vault.lock(200 ether);

        // EXPECTED (`_bank` NatSpec): a bank older than BACKING_WARMUP is forfeited; the returning 200 warm
        // from zero, so the stored lag does not move at the lock.
        // ACTUAL: the bank was re-dated by each one-wei withdrawal and the 200 are credited at once.
        // (A few wei of tolerance: the one-wei withdrawals of the last day may themselves be credited back.)
        assertLt(vault.laggedSecured(), laggedBeforeReturn + 1 ether, "capital away for five days warms again like new capital");
    }
}
